import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry,
    Color, AmbientLight, DirectionalLight, DoubleSide,
  } = THREE;

  const colors =
    (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) ||
    config.colors ||
    { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  const group = new Group();
  group.name = 'journal-thumbnail-card';

  // --- geometry setup: image plane 1.6 ratio + caption strip below ---
  const cardW = 1.8;
  const imgH = 1.125;          // 1.8 / 1.125 = 1.6
  const stripH = 0.24;
  const cardH = imgH + stripH;  // 1.365
  const depth = 0.06;

  // --- machined-metal frame panel (slight extrusion) ---
  const frameGeo = new BoxGeometry(cardW + 0.05, cardH + 0.05, depth);
  const frameMat = new MeshStandardNodeMaterial({
    color: ink,
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.18,
    clearcoatRoughness: 0.45,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -depth / 2 - 0.001;
  group.add(frame);

  // --- image plane ---
  const imgGeo = new PlaneGeometry(cardW, imgH);
  const imgMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.y = stripH / 2;
  imgMesh.position.z = 0.002;
  group.add(imgMesh);

  let imgTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgTex = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // --- caption strip (near-black surface) ---
  const stripGeo = new PlaneGeometry(cardW, stripH);
  const stripMat = new MeshStandardNodeMaterial({
    color: surface,
    metalness: 0.4,
    roughness: 0.65,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.y = -imgH / 2;
  strip.position.z = 0.002;
  group.add(strip);

  // --- accent edge (signal red) at image/strip junction ---
  const edgeGeo = new PlaneGeometry(cardW, 0.018);
  const edgeMat = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.4,
    metalness: 0.0,
    roughness: 0.4,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.y = -imgH / 2 + 0.001;
  edge.position.z = 0.004;
  group.add(edge);

  // --- lighting (node-local; standard materials need it) ---
  const ambient = new AmbientLight(paper.getHex(), 0.45);
  group.add(ambient);

  const key = new DirectionalLight(paper.getHex(), 1.1);
  key.position.set(2.2, 2.6, 3.0);
  group.add(key);

  const rim = new DirectionalLight(accent.getHex(), 0.75);
  rim.position.set(-2.6, -1.4, -1.8);
  group.add(rim);

  // --- interaction state ---
  let basePos = null;
  const ensureBase = () => {
    if (!basePos) basePos = { x: group.position.x, y: group.position.y, z: group.position.z };
  };

  let hoverTl = null;
  let pressTl = null;
  let focusTl = null;
  let focused = false;

  const handlers = {
    onPointerEnter: () => {
      ensureBase();
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: basePos.y + 0.15, duration: 0.6, ease: 'power3.out' });
      hoverTl.to(edgeMat, { emissiveIntensity: 2.1, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(frame.position, { z: -depth / 2 + 0.02, duration: 0.6, ease: 'power3.out' }, 0);
    },
    onPointerLeave: () => {
      ensureBase();
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, { y: basePos.y, duration: 0.5, ease: 'power3.out' });
      hoverTl.to(edgeMat, { emissiveIntensity: focused ? 1.9 : 1.4, duration: 0.4, ease: 'power2.out' }, 0);
      hoverTl.to(frame.position, { z: -depth / 2 - 0.001, duration: 0.5, ease: 'power3.out' }, 0);
    },
    onPointerDown: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' });
      pressTl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.22, ease: 'back.out(2.2)' });
    },
    onPointerClick: () => {
      ctx.emit('hub-journal.select', { from: config.id || 'hub-journal-thumbnail' });
    },
    onFocus: () => {
      focused = true;
      if (focusTl) focusTl.kill();
      focusTl = gsap.to(edgeMat, { emissiveIntensity: 1.9, duration: 0.3, ease: 'power2.out' });
    },
    onBlur: () => {
      focused = false;
      if (focusTl) focusTl.kill();
      focusTl = gsap.to(edgeMat, { emissiveIntensity: 1.4, duration: 0.3, ease: 'power2.out' });
    },
  };
  group.userData.handlers = handlers;

  // --- cleanup ---
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    if (focusTl) focusTl.kill();
    frameGeo.dispose();
    frameMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    if (imgTex && typeof imgTex.dispose === 'function') imgTex.dispose();
  };

  return group;
}
